import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.BPyF_sP4.js";const g=JSON.parse('{"title":"阅读指南","description":"","frontmatter":{"title":"阅读指南","bookSource":"website/reading-guide.md","readingMinutes":2,"prev":false,"next":false,"editLink":false},"headers":[],"relativePath":"reading-guide.md","filePath":"website/reading-guide.md","lastUpdated":1791620050000}'),i={name:"reading-guide.md"};function o(h,a,l,d,s,p){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="阅读指南" tabindex="-1">阅读指南 <a class="header-anchor" href="#阅读指南" aria-label="Permalink to &quot;阅读指南&quot;">​</a></h1><p>这本白皮书围绕一个共同问题展开：怎样把模型能力变成可以交付、运行、治理和持续改进的 Agent 系统。你可以从头阅读，也可以带着当前的工程问题进入相应章节。</p><h2 id="第一次系统了解-agent" tabindex="-1">第一次系统了解 Agent <a class="header-anchor" href="#第一次系统了解-agent" aria-label="Permalink to &quot;第一次系统了解 Agent&quot;">​</a></h2><p>先读<a href="/ai-agent-handbook/survey.html">开发者调研报告</a>，了解企业落地的现状；再读<a href="/ai-agent-handbook/architecture/">架构篇</a>，建立 Model、Harness 和 Agent Platform 的共同语言。<a href="/ai-agent-handbook/build/">构建篇</a>进一步解释任务、信息与行动怎样组成一个可工作的 Agent。</p><p>推荐顺序：调研报告 → 第1—2章 → 第3—6章 → 第13—16章。</p><h2 id="正在把-agent-接入生产" tabindex="-1">正在把 Agent 接入生产 <a class="header-anchor" href="#正在把-agent-接入生产" aria-label="Permalink to &quot;正在把 Agent 接入生产&quot;">​</a></h2><p>从<a href="/ai-agent-handbook/run/">运行篇</a>开始，关注执行环境、持久状态、网关和长任务。随后进入<a href="/ai-agent-handbook/governance/">治理篇</a>，检查观测、授权、资产管理和上线验证是否覆盖完整任务。</p><p>推荐顺序：第7—9章 → 第10章 → 第13—14章 → 第18—23章。</p><h2 id="正在建设多-agent-系统" tabindex="-1">正在建设多 Agent 系统 <a class="header-anchor" href="#正在建设多-agent-系统" aria-label="Permalink to &quot;正在建设多 Agent 系统&quot;">​</a></h2><p>先通过<a href="/ai-agent-handbook/build/chapter-04.html">第4章</a>和<a href="/ai-agent-handbook/build/chapter-06.html">第6章</a>明确任务、委派和行动边界，再读运行篇的<a href="/ai-agent-handbook/run/chapter-10.html">异步任务</a>、<a href="/ai-agent-handbook/run/chapter-11.html">协作编排</a>与<a href="/ai-agent-handbook/run/chapter-12.html">分布式通信</a>，最后用观测与质量验证检查整体结果。</p><p>推荐顺序：第4—6章 → 第10—12章 → 第13、16章。</p><h2 id="负责评估与持续优化" tabindex="-1">负责评估与持续优化 <a class="header-anchor" href="#负责评估与持续优化" aria-label="Permalink to &quot;负责评估与持续优化&quot;">​</a></h2><p>从<a href="/ai-agent-handbook/optimization/chapter-18.html">第18章调优总览</a>建立数据飞轮的完整视图，再依次理解轨迹、数据处理、黄金数据集、Badcase 和受控自进化。需要改变模型本身时，再进入<a href="/ai-agent-handbook/optimization/chapter-17.html">第17章模型调优</a>。</p><p>推荐顺序：第13章 → 第18—23章 → 第17、24章 → 相关实践案例。</p><h2 id="负责选型或项目立项" tabindex="-1">负责选型或项目立项 <a class="header-anchor" href="#负责选型或项目立项" aria-label="Permalink to &quot;负责选型或项目立项&quot;">​</a></h2><p>先读调研报告和第1—3章，明确业务目标与构建方式；按行业或岗位进入<a href="/ai-agent-handbook/cases/">实践篇</a>，对照投入、边界和交付结果；最后读<a href="/ai-agent-handbook/outlook/chapter-30.html">第30章</a>，理解平台演进的长期方向。</p><h2 id="怎样使用这个阅读站" tabindex="-1">怎样使用这个阅读站 <a class="header-anchor" href="#怎样使用这个阅读站" aria-label="Permalink to &quot;怎样使用这个阅读站&quot;">​</a></h2><ul><li>左侧目录组织全书篇章，右侧目录定位当前章节的小节。</li><li>“搜索全书”支持中文主题和英文术语，结果可以直接定位到相关段落。</li><li>文末的上一篇和下一篇可以连续阅读；阅读位置保存在当前浏览器，首页可继续上次阅读。</li><li>点击正文图片可放大查看。架构图支持单独打开，宽表格和代码块可以横向滚动。</li><li>可以调整正文字号、切换明暗主题，或打印当前章节。</li><li>发现内容问题时，可从页面的反馈入口提交 Issue，或通过“在 GitHub 上完善本页”参与编辑。</li></ul>',18)])])}const u=e(i,[["render",o]]);export{g as __pageData,u as default};
